const int UF = 4;
data_t buf[N];
#pragma HLS ARRAY_PARTITION variable=buf cyclic factor=UF dim=1
data_t partial[UF];
#pragma HLS ARRAY_PARTITION variable=partial complete

data_t lane_buf[LANES];
#pragma HLS ARRAY_PARTITION variable=lane_buf complete dim=1

for (int lane = 0; lane < LANES; ++lane) {
#pragma HLS UNROLL
    ... lane_buf[lane] ...
}

#pragma HLS ARRAY_PARTITION variable=local_A cyclic factor=UF dim=2
#pragma HLS DATAFLOW
load_A_task(...);   // gmem0
load_B_task(...);   // gmem1 — parallel with load_A
compute_tile_task(...);
store_C_task(...);

// inside compute:
for (int j = 0; j < N; j += UF) {
#pragma HLS PIPELINE II=1
    for (int k = 0; k < UF; k++) {
#pragma HLS UNROLL
        acc += local_A[i][j+k] * local_B[j+k][l];
    }
}

const int UF = 4;
double partial[UF];
#pragma HLS ARRAY_PARTITION variable=partial complete
for (int p = 0; p < UF; p++) {
#pragma HLS UNROLL
    partial[p] = 0.0;
}
for (int k = 0; k < TILE_SIZE; k += UF) {
#pragma HLS PIPELINE II=1
    for (int p = 0; p < UF; p++) {
#pragma HLS UNROLL
        if (k + p < j) partial[p] += expr(k + p);
    }
}
double sum = 0; for (int p = 0; p < UF; p++) { #pragma HLS UNROLL sum += partial[p]; }

// Rectangular GEMM
#pragma HLS ARRAY_PARTITION variable=A_local complete dim=2
#pragma HLS ARRAY_PARTITION variable=B_local complete dim=1
compute: for (int i = 0; i < M; ++i) {
  for (int j = 0; j < N; ++j) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_FLATTEN
    T sum = 0;
    for (int k = 0; k < K; ++k) {
#pragma HLS UNROLL
      sum += A_local[i][k] * B_local[k][j];
    }
    C_local[i][j] = sum;
  }
}
// syr2k/syrk triangle (fixed bounds + guard; k unrolled)
#pragma HLS ARRAY_PARTITION variable=A_local complete dim=2
#pragma HLS ARRAY_PARTITION variable=B_local complete dim=2
scale: for (int i = 0; i < N; ++i)
  for (int j = 0; j < N; ++j) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_FLATTEN
    if (j <= i) C_local[i][j] *= beta;
  }
update: for (int i = 0; i < N; ++i)
  for (int j = 0; j < N; ++j) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_FLATTEN
    if (j <= i) {
      double sum = 0;
      for (int k = 0; k < M; ++k) {
#pragma HLS UNROLL
        sum += A_local[j][k]*B_local[i][k] + B_local[j][k]*A_local[i][k];
      }
      C_local[i][j] += alpha * sum;
    }
  }

// GEMM on locals: bank the reduction dimension so (i,j) can flatten with II=1
#pragma HLS ARRAY_PARTITION variable=A_local complete dim=2  // k
#pragma HLS ARRAY_PARTITION variable=B_local complete dim=1  // k
// or: cyclic factor=UNROLL_K on those dims if complete is too heavy

// Complete: small fully parallel dimension
#pragma HLS ARRAY_PARTITION variable=small_buf complete dim=1

// Cyclic: lane-indexed interleaved access
#pragma HLS ARRAY_PARTITION variable=buf cyclic factor=UNROLL_FACTOR dim=1

// Block: each worker owns a contiguous block
#pragma HLS ARRAY_PARTITION variable=buf block factor=PE dim=1

// GEMM: pipeline+flatten (i,j); fully unroll k with matching partition
for (int i = 0; i < M; ++i) {
  for (int j = 0; j < N; ++j) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_FLATTEN
    T sum = 0;
    for (int k = 0; k < K; ++k) {
#pragma HLS UNROLL
      sum += A[i][k] * B[k][j];
    }
    C[i][j] = sum;
  }
}
// Non-GEMM small inner under a truly outer pipeline:
OUTER: for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
    INNER: for (int j = 0; j < SMALL_BOUND; ++j) {
#pragma HLS UNROLL
        ...
    }
}

#pragma HLS ARRAY_PARTITION variable=local_A complete dim=2
#pragma HLS ARRAY_PARTITION variable=local_B complete dim=2
// optional: partition local_C cyclic/complete on dim=2 if needed for II
scale: for (int i = 0; i < N; ++i) {
  for (int j = 0; j < N; ++j) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_FLATTEN
    if (j <= i) local_C[i][j] *= beta;
  }
}
update: for (int i = 0; i < N; ++i) {
  for (int j = 0; j < N; ++j) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_FLATTEN
    if (j <= i) {
      double sum = 0.0;
      for (int k = 0; k < M; ++k) {
#pragma HLS UNROLL
        sum += local_A[j][k] * local_B[i][k] + local_B[j][k] * local_A[i][k];
      }
      local_C[i][j] += alpha * sum;
    }
  }
}

#pragma HLS ARRAY_PARTITION variable=tile cyclic factor=UNROLL_FACTOR dim=1

compute_tile: for (int i = 0; i < TILE; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
    inner: for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
        int local_idx = i + lane;
        if (local_idx < TILE) out_tile[local_idx] = f(tile[local_idx]);
    }
}

data_t tile[TILE];
#pragma HLS ARRAY_PARTITION variable=tile cyclic factor=UNROLL_FACTOR dim=1

for (int i = 0; i < TILE; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
    for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
        ... tile[i + lane] ...
    }
}

const int UF = 4;
data_t A_local[N][N];
data_t y_local[N];
#pragma HLS ARRAY_PARTITION variable=A_local cyclic factor=UF dim=2
#pragma HLS ARRAY_PARTITION variable=y_local cyclic factor=UF dim=1

for (int k = 0; k < UF; k++) {
#pragma HLS UNROLL
    partial[k] += A_local[i][j + k] * y_local[j + k];
}

// Small static N: complete unroll
for (int j = 0; j < N; ++j) {
#pragma HLS UNROLL
  ...
}
// Large N under budget pressure: partial with matching partition
for (int j = 0; j < N; j += UF) {
#pragma HLS PIPELINE II=1
  for (int lane = 0; lane < UF; ++lane) {
#pragma HLS UNROLL
    int idx = j + lane; if (idx < N) ...;
  }
}

data_t in_buf[PE][ITEMS_PER_PE];
#pragma HLS ARRAY_PARTITION variable=in_buf complete dim=1

PE_LOOP: for (int pe = 0; pe < PE; ++pe) {
#pragma HLS UNROLL
    process_items(in_buf[pe], out_buf[pe]);
}

data_t partial[UNROLL_FACTOR];
#pragma HLS ARRAY_PARTITION variable=partial complete dim=1

for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
    partial[lane] = 0;
}

LOOP: for (int i = 0; i < N; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
    for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
        int idx = i + lane;
        if (idx < N) partial[lane] += f(in[idx]);
    }
}
// Final reduction across partial[lane].

data_t buf[N];
#pragma HLS ARRAY_PARTITION variable=buf cyclic factor=UNROLL_FACTOR dim=1

LOOP: for (int i = 0; i < N; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
    for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
        ... buf[i + lane] ...
    }
}

data_t buf[TILE];
#pragma HLS ARRAY_PARTITION variable=buf cyclic factor=UNROLL_FACTOR dim=1

for (int i = 0; i < TILE; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
    lane_loop: for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
        int idx = i + lane;
        ... buf[idx] ...
    }
}

data_t small_buf[UNROLL_FACTOR];
#pragma HLS ARRAY_PARTITION variable=small_buf complete dim=1

loop: for (int i = 0; i < N; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
    lanes: for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
        ... small_buf[lane] ...
    }
}

coef_t coeff_lane[LANES][K];
#pragma HLS ARRAY_PARTITION variable=coeff_lane complete dim=1

lanes: for (int lane = 0; lane < LANES; ++lane) {
#pragma HLS UNROLL
    y_lane[lane] = use_coeff(coeff_lane[lane], x_lane[lane]);
}

data_t partial[UNROLL_FACTOR];
#pragma HLS ARRAY_PARTITION variable=partial complete dim=1

init: for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
    partial[lane] = 0;
}

main: for (int i = 0; i < N; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
    lanes: for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
        int idx = i + lane;
        if (idx < N) partial[lane] += f(in[idx]);
    }
}

// Final tree or loop reduction over partial[lane].

state_t state_lane[LANES];
#pragma HLS ARRAY_PARTITION variable=state_lane complete dim=1

lanes: for (int lane = 0; lane < LANES; ++lane) {
#pragma HLS UNROLL
    out_lane[lane] = step(in_lane[lane], state_lane[lane]);
}

data_t acc_priv[LANES][BINS];
#pragma HLS ARRAY_PARTITION variable=acc_priv complete dim=1

update_loop: for (int i = 0; i < N; i += LANES) {
#pragma HLS PIPELINE II=1
    lane_loop: for (int lane = 0; lane < LANES; ++lane) {
#pragma HLS UNROLL
        int idx = i + lane;
        if (idx < N) acc_priv[lane][key[idx]] += val[idx];
    }
}

merge_bins: for (int b = 0; b < BINS; ++b) {
#pragma HLS PIPELINE II=1
    data_t sum = 0;
    for (int lane = 0; lane < LANES; ++lane) {
#pragma HLS UNROLL
        sum += acc_priv[lane][b];
    }
    acc[b] = sum;
}

data_t acc_reg = acc[0];
loop: for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
    acc_reg = update(acc_reg, in[i]);
}
acc[0] = acc_reg;

float buf[N];
#pragma HLS ARRAY_PARTITION variable=buf cyclic factor=4 dim=1

LOOP: for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
    ... buf[i] ... buf[i + 1] ...
}

// Preferred for small static N (e.g. N<=64):
#pragma HLS ARRAY_PARTITION variable=local_A complete dim=2
compute: for (int i = 0; i < M; ++i) {
#pragma HLS PIPELINE II=1
  for (int j = 0; j < N; ++j) {
#pragma HLS UNROLL
    ... local_A[i][j] ...
  }
}
// Only if resources explode, fall back to partial with MATCHING partition:
// #pragma HLS ARRAY_PARTITION variable=local_A cyclic factor=UF dim=2
// #pragma HLS UNROLL factor=UF
